    /// <summary>
    /// hide/show controls when modifying location field
    /// </summary>
    /// <param name="sender">FormDataObject</param>
    /// <param name="e">FormDataFieldEventArgs</param>
    [FormDataFieldEventHandler(formDataFieldStr(DocuType, DocuType, FilePlace), FormDataFieldEventType::Modified),
    SuppressBPWarning('BPParameterNotUsed', 'False positive')]
    public static void FilePlace_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        DocuType docuType = sender.datasource().cursor();
        const str emptyStr = '';
        
        boolean isAzureStorage = docuType.FilePlace == DocuFilePlace::METAzureStorage? true : false;

        FormRun formRun = sender.datasource().formRun();

        FormGroupControl azureStorageGroup = formRun.design().controlName(formControlStr(DocuType, METAzureStorageGroup));
        FormGroupControl sharePointLocationGroup = formRun.design().controlName(formControlStr(DocuType, SharePointLocationGroup));

        FormStringControl storageAccountName = formRun.design().controlName(formControlStr(DocuType, METAzureStorageGroup_METAzureStorageAccountName));
        FormStringControl storageSecret = formRun.design().controlName(formControlStr(DocuType, METAzureStorageGroup_METAzureStorageSecret));;
        FormStringControl storageContainerName = formRun.design().controlName(formControlStr(DocuType, METAzureStorageGroup_METAzureStorageContainerName));;
        FormStringControl storageFolder = formRun.design().controlName(formControlStr(DocuType, METAzureStorageGroup_METAzureStorageFolder));;

        storageAccountName.mandatory(isAzureStorage);
        storageSecret.mandatory(isAzureStorage);
        storageContainerName.mandatory(isAzureStorage);
        storageFolder.mandatory(isAzureStorage);

        if (azureStorageGroup)
        {
            azureStorageGroup.visible(isAzureStorage);
        }

        if (sharePointLocationGroup)
        {
            sharePointLocationGroup.visible(!isAzureStorage);
        }

        if (!isAzureStorage)
        {
            docuType.METAzureStorageAccountName = emptyStr;
            docuType.METAzureStorageContainerName = emptyStr;
            docuType.METAzureStorageFolder = emptyStr;
            docuType.METAzureStorageSecret = emptyStr;
        }
    }

    /// <summary>
    /// hide/show controls when selecting MET Azure Storage location
    /// </summary>
    /// <param name="sender">FormDataSource</param>
    /// <param name="e">FormDataSourceEventArgs</param>
    [FormDataSourceEventHandler(formDataSourceStr(DocuType, DocuType), FormDataSourceEventType::Activated),
    SuppressBPWarning('BPParameterNotUsed', 'False positive')]
    public static void DocuType_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        DocuType docuType = sender.cursor();
        //const str emptyStr = '';
        
        boolean isAzureStorage = docuType.FilePlace == DocuFilePlace::METAzureStorage? true : false;

        FormGroupControl azureStorageGroup = sender.formRun().design().controlName(formControlStr(DocuType, METAzureStorageGroup));
        FormGroupControl sharePointLocationGroup = sender.formRun().design().controlName(formControlStr(DocuType, SharePointLocationGroup));

        if (azureStorageGroup)
        {
            azureStorageGroup.visible(isAzureStorage);
        }   
     
        if (sharePointLocationGroup)
        {
            sharePointLocationGroup.visible(!isAzureStorage);
        }

    }
